Map<String,Long> counts=new HashMap<>();
long deadline=System.nanoTime()+Duration.ofSeconds(5).toNanos();
while(System.nanoTime()<deadline){for(var e:Thread.getAllStackTraces().entrySet()){if(!e.getKey().isAlive())continue;String folded=Arrays.stream(e.getValue()).map(f->f.getClassName()+"."+f.getMethodName()).collect(Collectors.joining(";"));counts.merge(folded,1L,Long::sum);}LockSupport.parkNanos(Duration.ofMillis(10).toNanos());}
